<?php if(!isset($listing)){http_response_code(404);exit;}$escape=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$url=static fn($v)=>$escape(appUrl($v));?><!DOCTYPE html><html lang="vi"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thông báo — Kanto</title><?php require __DIR__.'/../../includes/head.php';?><?php foreach(['style','student-dashboard','navbar','approval','notifications'] as $css):?><link rel="stylesheet" href="<?= $url('assets/css/'.$css.'.css') ?>"><?php endforeach;?></head><body class="student-page"><?php require __DIR__.'/../../includes/student-header.php';?><div class="dashboard-layout"><?php require __DIR__.'/../../includes/navbar.php';?><main class="student-main notification-main"><h1>Thông báo</h1><p class="staff-intro">Các thông báo dành cho tài khoản sinh viên của bạn.</p><section class="approval-panel notification-list"><?php foreach($listing['items'] as $item):?><article><div><h2><a href="<?= $url('index.php?action=notification-detail&id='.rawurlencode($item['MaThongBao'])) ?>"><?= $escape($item['TieuDe']) ?></a></h2><time><?= $escape($item['ThoiGianTao']) ?></time></div><p><?= $escape(mb_strimwidth($item['NoiDung'],0,180,'…','UTF-8')) ?></p><?php if($item['MaHoaDon']):?><span>Hóa đơn: <?= $escape($item['MaHoaDon']) ?></span><?php endif;?></article><?php endforeach;?><?php if(!$listing['items']):?><p>Bạn chưa có thông báo nào.</p><?php endif;?></section><nav class="notification-pagination"><?php if($listing['page']>1):?><a class="approval-button" href="<?= $url('index.php?action=notifications&page='.($listing['page']-1)) ?>">Trang trước</a><?php endif;?><?php if($listing['page']<$listing['pages']):?><a class="approval-button" href="<?= $url('index.php?action=notifications&page='.($listing['page']+1)) ?>">Trang sau</a><?php endif;?></nav></main></div></body></html>
